export type Group = 1 | 2 | 3;

export type FormKey =
  | 'dict' | 'masu' | 'nai' | 'ta' | 'nakatta' | 'te' | 'tari' | 'nakereba';

export type Forms = Record<FormKey, string>;

/* ---------- Normalized model (tables) — see docs/schema.html ----------
 * Generated by scripts/migrate.mjs; consumed by lib/db.ts. */

/** A lexicon word. Verb attributes (group, falseG2) only when kind='verb'.
 *  Furigana: `furi` reads ONLY over the kanji; `okuri` stays as loose kana —
 *  so you can see whether the い/え vowel sits inside the kanji (usually Group 1)
 *  or in the okurigana (Group 2). */
export type ItemKind = 'verb' | 'noun' | 'adj_i' | 'adj_na' | 'phrase';
export interface Item {
  id: string;
  kind: ItemKind;
  kanji?: string;
  furi?: string;
  okuri?: string;
  kana: string;
  meaning: string;
  group?: Group;      // verbs only
  falseG2?: boolean;  // verbs only
}

/** One question row. `skill` = pedagogical axis; `type` = how it's rendered and graded. */
export type Skill = 'grammar' | 'vocab' | 'conjugation' | 'kanji';
export type ExerciseType = 'mc' | 'type' | 'conjugate';
export interface Exercise {
  id: string;
  skill: Skill;
  type: ExerciseType;
  chapter?: number;
  topic?: string;
  prompt?: string;
  cue?: string;
  exp?: string;
  options?: string[];    // type=mc
  correct?: number;      // type=mc
  answers?: string[];    // type=type
  itemId?: string;       // → Item.id (conjugate / vocab)
  params?: Record<string, unknown>; // conjugate config (what to ask / mode)
}

/** Ordered group of exercises — the Duolingo-style path. */
export interface Lesson {
  id: string;
  title: string;
  subtitle?: string;
  position: number;
  chapter?: number;
  exerciseIds: string[];
}

/* ---------- Kanji (Basic Kanji Book vol. 1) ---------- */

/** Readings as printed in the BKB index: on in katakana, kun in hiragana with `-`
 *  before the okurigana (あたら-しい). Only the readings the book teaches. */
export interface Kanji {
  id: string;
  char: string;
  lesson: number;
  on: string[];
  kun: string[];
  meaning: string;
}

/** A word written only with BKB1 kanji. `ruby` ([新|しん][聞|ぶん]) is the source of
 *  truth: written form, kana and lesson are derived from it (lib/kanji.ts).
 *  A multi-kanji block ([今日|きょう]) is a reading of the whole (jukujikun).
 *  `alt` = other correct readings, never offered as distractors. */
export type WordKind = 'noun' | 'verb' | 'adj_i' | 'adj_na' | 'other';
export interface KanjiWord {
  id: string;
  ruby: string;
  kind: WordKind;
  meaning: string;
  alt?: string[];
}
